var PHOTO="data:image/webp;base64,";
(function(){
  var reduce=matchMedia('(prefers-reduced-motion:reduce)').matches;
  document.getElementById('pimg').src=PHOTO;
  function tilt(el,max){
    if(reduce)return;
    el.addEventListener('pointermove',function(e){var r=el.getBoundingClientRect(),x=(e.clientX-r.left)/r.width-.5,y=(e.clientY-r.top)/r.height-.5;el.style.transform='perspective(900px) rotateX('+(-y*max)+'deg) rotateY('+(x*max)+'deg)';});
    el.addEventListener('pointerleave',function(){el.style.transform='';});
  }
  tilt(document.getElementById('photo'),14);
  document.querySelectorAll('.proj').forEach(function(p){tilt(p,6)});

  /* pipeline */
  var st=document.querySelectorAll('.st'),log=document.getElementById('log'),status=document.getElementById('status');
  var msgs=['git checkout main','docker build -t flask-app .','docker push flask-app:latest','deploying to staging'],i=0;
  function fin(){status.innerHTML='<b style="color:var(--ok)">Passed</b>';log.innerHTML='<b>Success</b> – deployed with one trigger';}
  function step(){
    if(i>=st.length){fin();return;}
    st[i].className='st run';status.textContent='Running';log.textContent='$ '+msgs[i];
    var n=i;setTimeout(function(){st[n].className='st done';i++;step();},900);
  }
  if(reduce){st.forEach(function(s){s.className='st done'});fin();}else{setTimeout(step,900);}

  /* 3D hero */
  var box=document.getElementById('scene'),ta=document.getElementById('ta'),tb=document.getElementById('tb'),R;
  if(!window.THREE){box.style.display='none';return;}
  try{R=new THREE.WebGLRenderer({antialias:true,alpha:true});}catch(e){box.style.display='none';return;}
  R.setPixelRatio(Math.min(devicePixelRatio||1,2));R.outputEncoding=THREE.sRGBEncoding;
  box.appendChild(R.domElement);
  var S=new THREE.Scene(),C=new THREE.PerspectiveCamera(35,1,.1,100);C.position.set(0,0,11);
  var G=new THREE.Group();S.add(G);
  var H=7,W=H*700/896,geo=new THREE.PlaneGeometry(W,H);
  new THREE.TextureLoader().load(PHOTO,function(tex){
    tex.encoding=THREE.sRGBEncoding;tex.anisotropy=4;
    var f=new THREE.Mesh(geo,new THREE.MeshBasicMaterial({map:tex,transparent:true}));
    var b=new THREE.Mesh(geo,new THREE.MeshBasicMaterial({map:tex,transparent:true,color:0x070a12}));
    b.rotation.y=Math.PI;b.position.z=-.01;G.add(f);G.add(b);draw(0);
  });
  var orbs=[];
  [[-4.2,2.6,-1,.5],[4.6,-2.2,-2,.7],[3.6,3,-3,.35]].forEach(function(p,k){
    var m=new THREE.Mesh(new THREE.IcosahedronGeometry(p[3],0),new THREE.MeshBasicMaterial({color:k?0x3DDC97:0x5B8CFF,wireframe:true,transparent:true,opacity:.7}));
    m.position.set(p[0],p[1],p[2]);m.userData.k=k;S.add(m);orbs.push(m);
  });
  function place(){var w=box.clientWidth,h=box.clientHeight;R.setSize(w,h,false);C.aspect=w/h;C.updateProjectionMatrix();G.position.x=w>760?2.2:0;G.position.y=w>760?-.2:.6;G.scale.setScalar(w>760?1:.8);}
  place();addEventListener('resize',place);
  var mx=0,my=0;addEventListener('pointermove',function(e){mx=e.clientX/innerWidth-.5;my=e.clientY/innerHeight-.5;});
  function ease(x){return x*x*(3-2*x);}
  function rot(t){var c=t%9;
    if(c<3.5)return 0;if(c<4.7)return Math.PI*ease((c-3.5)/1.2);
    if(c<7.2)return Math.PI;if(c<8.4)return Math.PI*(1-ease((c-7.2)/1.2));return 0;}
  function draw(t){
    var r=rot(t),c=Math.cos(r);
    G.rotation.y=r+mx*.35;G.rotation.x=my*.15;
    ta.style.opacity=Math.max(0,Math.min(1,c*2));tb.style.opacity=Math.max(0,Math.min(1,-c*2));
    orbs.forEach(function(o){o.rotation.x=t*.6+o.userData.k;o.rotation.y=t*.8;o.position.y+=Math.sin(t*1.2+o.userData.k)*.003;});
    R.render(S,C);
  }
  if(reduce){draw(0);return;}
  var t0=performance.now();
  (function loop(){draw((performance.now()-t0)/1000);requestAnimationFrame(loop);})();
})();
